function minimizeSum(nums) {
  nums.sort((a, b) => a - b);
  const n = nums.length;
  // Each changed value copies a kept one, so the low score is always 0.
  // Only the spread of the kept values remains: drop two extremes.
  const dropTwoSmallest = nums[n - 1] - nums[2];
  const dropTwoLargest = nums[n - 3] - nums[0];
  const dropOneEach = nums[n - 2] - nums[1];
  return Math.min(dropTwoSmallest, dropTwoLargest, dropOneEach);
}

