function minimizeSum(nums) {
  const n = nums.length;
  const score = (arr) => {
    let low = Infinity;
    let high = 0;
    for (let i = 0; i < arr.length; i++) {
      for (let j = i + 1; j < arr.length; j++) {
        const d = Math.abs(arr[i] - arr[j]);
        low = Math.min(low, d);
        high = Math.max(high, d);
      }
    }
    return low + high;
  };
  const values = [...new Set(nums)];
  let best = Infinity;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      for (const a of values) {
        for (const b of values) {
          const changed = [...nums];
          changed[i] = a;
          changed[j] = b;
          best = Math.min(best, score(changed));
        }
      }
    }
  }
  return best;
}

