function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const top = [1000, 1000000000][int(0, 1)];
    return [Array.from({ length: 2000 }, () => int(1, top))];
  }
  const n = int(3, 7);
  const top = [3, 20, 1000000000][int(0, 2)];
  return [Array.from({ length: n }, () => int(1, top))];
}
